"use strict";(self.webpackChunkbellplay_docs=self.webpackChunkbellplay_docs||[]).push([[48891],{85319:e=>{e.exports=JSON.parse('{"tag":{"label":"freeverb","permalink":"/docs/tags/freeverb","allTagsPath":"/docs/tags","count":10,"items":[{"id":"learn/tutorials/bufferprocessing","title":"10. Buffer processing","description":"One of the core features of bellplay~ is the ability to dynamically and flexibly apply chains of DSP algorithms to our buffers.","permalink":"/docs/learn/tutorials/bufferprocessing"},{"id":"learn/examples/temporalalignment","title":"11. Envelope-aware temporal alignment","description":"This example demonstrates how to align the envelopes of different audio samples based on their peak amplitude times.","permalink":"/docs/learn/examples/temporalalignment"},{"id":"learn/tutorials/postprocessing","title":"11. Post-rendering processing","description":"Sometimes it can be more useful or desirable to apply processing to the entire output, instead of processing each buffer individually.","permalink":"/docs/learn/tutorials/postprocessing"},{"id":"learn/examples/shepardtone","title":"12. Shepard-Risset glissando","description":"This example synthesizes a Shepard-Risset glissando using bellplay~.","permalink":"/docs/learn/examples/shepardtone"},{"id":"learn/tutorials/multirendering","title":"20. Multi-rendering","description":"This tutorial demonstrates a very simple but consequential feature in bellplay~\u2014namely, the ability to reuse rendered buffers multiple times to further refine and sculpt the final output into complex and intricate sounds.","permalink":"/docs/learn/tutorials/multirendering"},{"id":"learn/tutorials/importingmidi","title":"22. Importing MIDI","description":"bellplay~ supports importing MIDI files (.mid or .midi) into our scripts, each described as a list of events.","permalink":"/docs/learn/tutorials/importingmidi"},{"id":"learn/tutorials/kdtree","title":"24. Feature-driven sampling","description":"This tutorial shows how to build k-dimensional trees to efficiently perform feature-based search on buffers.","permalink":"/docs/learn/tutorials/kdtree"},{"id":"learn/examples/syntharpeggio","title":"4. Synth arpeggio","description":"This example demonstrates how to use BPFs to continuously change the pitch of different oscillators.","permalink":"/docs/learn/examples/syntharpeggio"},{"id":"learn/examples/gliss","title":"6. Glissando texture","description":"An example of using time-varying resampling to generate a polyphonic texture.","permalink":"/docs/learn/examples/gliss"},{"id":"learn/examples/midiretuning","title":"8. MIDI retuning","description":"An example of JI-based retuning of MIDI events.","permalink":"/docs/learn/examples/midiretuning"}],"unlisted":false}}')}}]);